package com.salespunch360.mobile.ui.account.sales
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.items;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.CustomerReceiptViewModel
@Composable fun CustomerReceiptScreen(padding:PaddingValues,vm:CustomerReceiptViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value,customers=s.customers.filter{it.branchId==s.branchId},invoices=s.invoices.filter{it.branchId==s.branchId&&it.customerId==s.customerId};LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Payment-In / Customer Receipt",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};if(s.loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())};s.error?.let{item{Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.errorContainer)){Row(Modifier.padding(12.dp)){Text(it,Modifier.weight(1f));TextButton(vm::refresh){Text("Retry")}}}}};s.message?.let{item{Text(it,color=MaterialTheme.colorScheme.primary)}};item{SelectField("Branch",s.branchId,s.branches.map{it.id to it.name}){id->vm.update{it.copy(branchId=id,customerId="",invoiceId="")}}};item{SelectField("Customer",s.customerId,customers.map{it.id to it.name}){id->vm.update{it.copy(customerId=id,invoiceId="")}}};item{SelectField("Invoice",s.invoiceId,invoices.map{it.id to "${it.number} · Outstanding ₹${it.outstanding}"}){id->val invoice=invoices.first{it.id==id};vm.update{it.copy(invoiceId=id,amount=invoice.outstanding)}}};item{OutlinedTextField(s.amount,{v->vm.update{it.copy(amount=v)}},label={Text("Amount")},modifier=Modifier.fillMaxWidth())};item{OutlinedTextField(s.date,{v->vm.update{it.copy(date=v)}},label={Text("Receipt date (YYYY-MM-DD)")},modifier=Modifier.fillMaxWidth())};item{SelectField("Payment method",s.mode,listOf("CASH" to "Cash","BANK" to "Bank")){v->vm.update{it.copy(mode=v)}}};item{SelectField("Money account",s.moneyAccountId,s.moneyAccounts.filter{it.branchId==null||it.branchId==s.branchId}.map{it.id to it.name}){v->vm.update{it.copy(moneyAccountId=v)}}};item{OutlinedTextField(s.reference,{v->vm.update{it.copy(reference=v)}},label={Text("Reference")},modifier=Modifier.fillMaxWidth())};item{OutlinedTextField(s.notes,{v->vm.update{it.copy(notes=v)}},label={Text("Notes")},modifier=Modifier.fillMaxWidth())};item{Button(vm::save,enabled=!s.saving&&s.customerId.isNotBlank()&&s.invoiceId.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text(if(s.saving)"Posting…" else "Post receipt")}};item{Text("Recent receipts",style=MaterialTheme.typography.titleLarge)};items(s.history,key={it.id}){ListItem(headlineContent={Text(it.number)},supportingContent={Text("${it.date} · ${it.mode}")},trailingContent={Text("₹${it.amount}")})}}}
